/** Element counts for a formula, e.g. "Ca(OH)2" => { Ca: 1, O: 2, H: 2 }. */
export function parseFormula(formula: string): Map<string, number> {
  const [counts, rest] = parseGroup(formula, 0);
  if (rest !== formula.length) {
    throw new Error(`Invalid formula "${formula}": unexpected character at index ${rest}`);
  }
  return counts;
}

function parseGroup(s: string, start: number): [Map<string, number>, number] {
  const counts = new Map<string, number>();
  let i = start;
  while (i < s.length) {
    const c = s[i];
    if (c === "(" || c === "[" || c === "{") {
      const close = c === "(" ? ")" : c === "[" ? "]" : "}";
      const [inner, after] = parseGroup(s, i + 1);
      if (after >= s.length || s[after] !== close) {
        throw new Error(`Invalid formula "${s}": unbalanced group at index ${i}`);
      }
      const [mult, next] = parseCount(s, after + 1);
      if (mult === 0) throw new Error(`Invalid formula "${s}": group multiplier must be positive`);
      for (const [el, n] of inner) add(counts, el, n * mult);
      i = next;
    } else if (c === ")" || c === "]" || c === "}") {
      return [counts, i]; // let caller handle the closer
    } else if (/[A-Z]/.test(c)) {
      let j = i + 1;
      while (j < s.length && /[a-z]/.test(s[j])) j++;
      const element = s.slice(i, j);
      const [n, next] = parseCount(s, j);
      add(counts, element, n);
      i = next;
    } else {
      throw new Error(
        `Invalid formula "${s}": unexpected character '${c}' at index ${i} ` +
          `(expected an element symbol like 'H'/'Fe', a digit, or an opening parenthesis)`
      );
    }
  }
  return [counts, i];
}

function parseCount(s: string, i: number): [number, number] {
  let j = i;
  while (j < s.length && /[0-9]/.test(s[j])) j++;
  return j === i ? [1, i] : [parseInt(s.slice(i, j), 10), j];
}

function add(map: Map<string, number>, key: string, value: number): void {
  map.set(key, (map.get(key) ?? 0) + value);
}

/**
 * Reduces a matrix over the rationals to reduced row echelon form in place.
 * Returns the list of pivot column indices (one per nonzero row).
 */
export function rref(matrix: Rational[][]): number[] {
  const rows = matrix.length;
  const cols = matrix[0]?.length ?? 0;
  const pivots: number[] = [];
  let row = 0;
  for (let col = 0; col < cols && row < rows; col++) {
    // Find a pivot in this column at or below the current row.
    let pivot = row;
    while (pivot < rows && matrix[pivot][col].isZero()) pivot++;
    if (pivot === rows) continue;
    [matrix[row], matrix[pivot]] = [matrix[pivot], matrix[row]];

    // Scale pivot row so the pivot is 1.
    const inv = matrix[row][col].div(matrix[row][col]); // pivot / pivot == 1
    void inv;
    const p = matrix[row][col];
    matrix[row] = matrix[row].map((v) => v.div(p));

    // Eliminate this column from all other rows.
    for (let r = 0; r < rows; r++) {
      if (r === row) continue;
      const factor = matrix[r][col];
      if (factor.isZero()) continue;
      for (let c = 0; c < cols; c++) {
        matrix[r][c] = matrix[r][c].sub(factor.mul(matrix[row][c]));
      }
    }
    pivots.push(col);
    row++;
  }
  return pivots;
}

/**
 * Balances a chemical equation of the form
 *   'A + B -> C + D'
 * and returns the smallest positive integer coefficient vector
 * [a_A, a_B, a_C, a_D].
 */
export function balance(equation: string): number[] {
  const arrow = equation.includes("->") ? "->" : null;
  if (!arrow) {
    throw new Error(
      `Cannot balance "${equation}": missing reaction arrow '->' between reactants and products`
    );
  }
  const [lhs, rhs] = equation.split("->");
  const reactants = splitSpecies(lhs, "reactant");
  const products = splitSpecies(rhs, "product");
  const species = [...reactants.map((f) => ({ formula: f, sign: 1 })), ...products.map((f) => ({ formula: f, sign: -1 }))];

  // Element inventory per species.
  const compositions = species.map(({ formula }) => parseFormula(formula.replace(/\s+/g, "")));
  const elements = [...new Set(compositions.flatMap((m) => [...m.keys()]))].sort();

  if (elements.size === 0 && elements.length === 0) {
    throw new Error("Cannot balance an equation with no chemical elements");
  }

  // Conservation law per element: sum(reactant coeff * count) - sum(product coeff * count) = 0.
  const m = elements.map((el) =>
    compositions.map((comp, j) => new Rational(species[j].sign * (comp.get(el) ?? 0)))
  );

  rref(m);

  const cols = species.length;
  const freeCols: number[] = [];
  for (let c = 0; c < cols; c++) if (!m.some((row) => !row[c].isZero())) freeCols.push(c);

  if (freeCols.length === 0) {
    throw new Error(
      `Cannot balance "${equation}": no non-trivial solution exists — the elements ` +
        `[${elements.join(", ")}] cannot be conserved by any choice of coefficients ` +
        `(the conservation system has full rank)`
    );
  }
  if (freeCols.length > 1) {
    throw new Error(
      `Cannot balance "${equation}": the equation has ${freeCols.length} degrees of freedom, ` +
        `so it does not determine unique relative amounts (e.g. two independent reactions mixed together)`
    );
  }

  // One-dimensional nullspace: set the single free variable to 1 and back-substitute.
  const free = freeCols[0];
  const solution: Rational[] = Array.from({ length: cols }, () => new Rational(0n));
  solution[free] = new Rational(1n);
  m.forEach((row, i) => {
    if (row[free].isZero()) return;
    const pivotCol = row.findIndex((v, c) => !v.isZero());
    solution[pivotCol] = row[free].neg();
  });

  // Scale rationals to integers: multiply by LCM of denominators...
  const scale = solution.reduce((acc, x) => lcm(acc, x.den), 1n);
  let ints = solution.map((x) => Number((x.num * scale) / x.den));
  // ...then reduce by the GCD to get the smallest coprime set.
  const g = ints.reduce((acc, v) => gcdInt(acc, Math.abs(v)), 0);
  ints = ints.map((v) => v / g);
  // Normalize sign so the first nonzero coefficient is positive.
  if (ints.every((v) => v <= 0)) ints = ints.map((v) => -v);

  if (ints.some((v) => v <= 0)) {
    throw new Error(
      `Cannot balance "${equation}": a balanced solution would require a non-positive ` +
        `coefficient (${ints.join(", ")}), which has no physical meaning`
    );
  }
  return ints;
}

function splitSpecies(side: string, label: string): string[] {
  const parts = side
    .split("+")
    .map((p) => p.trim())
    .filter((p) => p.length > 0);
  if (parts.length === 0) {
    throw new Error(`Equation is missing ${label}s on one side of the arrow`);
  }
  return parts;
}

function gcdInt(a: number, b: number): number {
  return b === 0 ? a : gcdInt(b, a % b);
}
