result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/balance.test.ts", "content": "import { describe, expect, it } from "vitest";
import { balance } from "../src/balance.js";
import { Rational } from "../src/rational.js";

/** Smallest positive-integer solution must be coprime as a set (gcd of all = 1). */
function gcdOfAll(xs: number[]): number {
  return xs.map(Math.abs).reduce((a, b) => {
    while (b) [a, b] = [b, a % b];
    return a;
  });
}

describe("Rational", () => {
  it("normalizes and does exact bigint arithmetic", () => {
    const half = new Rational(1n, 2n);
    const third = new Rational(2n, 6n); // -> 1/3
    expect(third.toString()).toBe("1/3");
    expect(half.add(third).toString()).toBe("5/6");
    expect(half.sub(third).toString()).toBe("1/6");
    expect(half.mul(third).toString()).toBe("1/6");
    expect(half.div(third).toString()).toBe("3/2");
    expect(new Rational(-2n, -4n).toString()).toBe("1/2");
    expect(new Rational(3n, -9n).toString()).toBe("-1/3");
    expect(() => new Rational(1n, 0n)).toThrow(/denominator/);
  });
});

describe("balance", () => {
  it.each([
    ["C2H6 + O2 -> CO2 + H2O", [2, 7, 4, 6]],
    ["P4 + O2 -> P2O5", [1, 5, 2]],
    ["Fe + O2 -> Fe2O3", [4, 3, 2]],
  ])("balances %s => %j", (equation, expected) => {
    const coeffs = balance(equation);
    expect(coeffs).toEqual(expected);
    // Coprime as a set: no common factor > 1 across all coefficients.
    expect(gcdOfAll(coeffs)).toBe(1);
    expect(coeffs.every((c) => c > 0)).toBe(true);
  });

  it("rejects equations with no non-trivial solution", () => {
    expect(() => balance("H2O -> H2O2")).toThrowError(
      /no non-trivial solution exists/
    );
  });

  it("handles nested parentheses", () => {
    // Ca + O2 + H2 -> Ca(OH)2  =>  Ca: 1, O2: 1, H2: 1, Ca(OH)2: 1
    expect(balance("Ca + O2 + H2 -> Ca(OH)2")).toEqual([1, 1, 1, 1]);
    // KMnO4 decomposition
    expect(balance("KMnO4 -> K2O + Mn2O7 + O2")).toEqual([4, 2, 2, 3]);
    for (const c of balance("KMnO4 -> K2O + Mn2O7 + O2")) expect(c).toBeGreaterThan(0);
  });
});
